pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address probe) internal {
        vm.assume(probe != address(0));
        address recordedOwner;
        try c.owner() returns (address __r) { recordedOwner = __r; } catch { return; }
        assertTrue(recordedOwner == address(this));
    }

    function testFuzz_run(address probe) public {
        vm.assume(probe.code.length == 0 && uint160(probe) > 0xffff && probe != address(this) && probe != address(c) && probe != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && probe != 0x000000000000000000636F6e736F6c652e6c6f67 && probe != 0x4e59b44847b379578588920cA78FbF26c0B4956C && probe != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(probe);
    }

    receive() external payable {}
}
